(() => {
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = { timer:$('timer'),level:$('level'),xpText:$('xpText'),xpFill:$('xpFill'),hpText:$('hpText'),hpFill:$('hpFill'),kills:$('kills'),waveText:$('waveText'),waveFill:$('waveFill'),damage:$('damageStat'),speed:$('speedStat'),weapon:$('weaponName'),armor:$('armorName'),bagCount:$('bagCount'),lootFeed:$('lootFeed'),toast:$('toast'),modal:$('modal'),levelModal:$('levelModal'),pauseModal:$('pauseModal'),endModal:$('endModal'),objective:$('objectiveText') };
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  let W=innerWidth,H=innerHeight,DPR=1, state='menu', last=0, elapsed=0, spawnClock=0, attackClock=0, shake=0, toastClock=0, sound=true, audioCtx=null;
  let keys={}, touch={x:0,y:0}, player, enemies=[], particles=[], drops=[], projectiles=[], decor=[], kills=0, level=1, xp=0, xpNeed=12, runLoot=[], wave=1, dashClock=0;
  const upgrades=[
    {icon:'⚔',name:'Sharpened Edge',desc:'Deal 25% more damage with every strike.',apply:()=>player.damage*=1.25},
    {icon:'✦',name:'Gravewalker Boots',desc:'Move 15% faster. The dead cannot catch smoke.',apply:()=>player.speed*=1.15},
    {icon:'♥',name:'Blood Tithe',desc:'Restore 35 vitality and increase maximum health by 10.',apply:()=>{player.maxHp+=10;player.hp=Math.min(player.maxHp,player.hp+35)}},
    {icon:'◉',name:'Honed Instinct',desc:'Strike 18% faster and find the gaps in their guard.',apply:()=>player.rate*=.82},
    {icon:'⌖',name:'Grasp of the Hollow',desc:'Draw experience and relics from 35% farther away.',apply:()=>player.magnet*=1.35},
    {icon:'☄',name:'Cinder Rune',desc:'Your blows burn with old magic, adding 8 damage.',apply:()=>player.damage+=8},
    {icon:'♧',name:'Stolen Breath',desc:'Recover 1 vitality every 3 seconds.',apply:()=>player.regen+=1/3}
  ];
  const itemTable=[
    {name:'Worn Bone Ring',rarity:'common',color:'#c6c2b9',icon:'◌',desc:'+4% attack speed'},
    {name:'Gloomfang',rarity:'magic',color:'#77b6da',icon:'⚔',desc:'+9 weapon damage'},
    {name:'Ashen Signet',rarity:'magic',color:'#77b6da',icon:'◉',desc:'+12% move speed'},
    {name:'Widowmaker',rarity:'rare',color:'#e6b564',icon:'✧',desc:'+20% strike power'},
    {name:'Crown of Cinders',rarity:'rare',color:'#e6b564',icon:'♛',desc:'+30 maximum vitality'},
    {name:'The Last Promise',rarity:'legendary',color:'#e58657',icon:'✹',desc:'A relic that remembers its owner'}
  ];
  function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=W*DPR;canvas.height=H*DPR;canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);document.body.classList.toggle('mobile',W<760)}
  addEventListener('resize',resize);resize();
  function fresh(){player={x:0,y:0,vx:0,vy:0,r:13,hp:100,maxHp:100,speed:190,damage:12,rate:.73,magnet:75,regen:0,invuln:0,facing:1,dash:0,dashDir:{x:1,y:0}};enemies=[];particles=[];drops=[];projectiles=[];decor=[];elapsed=0;spawnClock=.5;attackClock=.35;shake=0;kills=0;level=1;xp=0;xpNeed=12;runLoot=[];wave=1;dashClock=0;for(let i=0;i<75;i++)decor.push({x:rand(-1200,1200),y:rand(-900,900),type:Math.random()<.54?'grass':'stone',r:rand(2,8),a:rand(.06,.3)});updateHud();$('level').textContent=1;$('weaponName').textContent='Rustbound Edge';$('armorName').textContent="Warden's Shroud";$('className').textContent='Grave Warden';ui.lootFeed.innerHTML='<div class="empty-find">The hollow has yet to yield...</div>'}
  function play(){fresh();state='playing';ui.modal.classList.add('hidden');ui.endModal.classList.add('hidden');ui.pauseModal.classList.add('hidden');last=performance.now();}
  $('startBtn').onclick=play;$('againBtn').onclick=play;$('resumeBtn').onclick=()=>{state='playing';ui.pauseModal.classList.add('hidden');last=performance.now()};$('restartBtn').onclick=play;
  $('soundBtn').onclick=()=>{sound=!sound;$('soundBtn').innerHTML=`♫ <span>SOUND ${sound?'ON':'OFF'}</span>`};
  function tone(freq,dur=.07,type='sine',vol=.025){if(!sound)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch(e){}}
  function showToast(txt){ui.toast.textContent=txt;ui.toast.classList.add('show');toastClock=1.8}
  function updateHud(){ui.level.textContent=level;ui.xpText.textContent=`${Math.floor(xp)} / ${xpNeed}`;ui.xpFill.style.width=(xp/xpNeed*100)+'%';ui.hpText.textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;ui.hpFill.style.width=(player.hp/player.maxHp*100)+'%';ui.kills.textContent=kills;ui.damage.textContent=Math.round(player.damage);ui.speed.textContent=Math.round(player.speed/1.9)+'%';ui.bagCount.textContent=`${runLoot.length} / 6`;ui.waveText.innerHTML=`${['I','II','III','IV','V','VI'][Math.min(5,wave-1)]} <span>—</span> ${['WANDERING DEAD','THE HOLLOW WAKES','BLOOD MOON','THE HUNT','CINDER LORDS','ENDLESS NIGHT'][Math.min(5,wave-1)]}`;ui.waveFill.style.width=(elapsed%60/60*100)+'%';}
  function spawnEnemy(){let a=rand(0,Math.PI*2),dist=Math.max(W,H)*.65+rand(40,170),x=player.x+Math.cos(a)*dist,y=player.y+Math.sin(a)*dist;let t=Math.random(),kind=t<.69?'shambler':t<.91?'runner':'brute';if(elapsed>80&&Math.random()<.08)kind='wraith';let data={shambler:[16,34,10,7,'#68725c'],runner:[10,68,7,5,'#8a594a'],brute:[42,22,25,15,'#655759'],wraith:[13,47,18,11,'#77929a']}[kind];enemies.push({x,y,r:data[0],speed:data[1]+elapsed*.04,hp:data[2]+elapsed*.15,max:data[2]+elapsed*.15,damage:data[3],kind,color:data[4],phase:rand(0,7),hit:0});}
  function nearest(){let best=null,bd=Infinity;for(let e of enemies){let d=(e.x-player.x)**2+(e.y-player.y)**2;if(d<bd){bd=d;best=e}}return best}
  function attack(){let target=nearest();if(!target)return;let dx=target.x-player.x,dy=target.y-player.y,d=Math.hypot(dx,dy)||1;player.facing=dx<0?-1:1;projectiles.push({x:player.x+dx/d*17,y:player.y+dy/d*17,vx:dx/d*440,vy:dy/d*440,life:.20,damage:player.damage,hit:new Set()});particles.push({x:player.x+dx/d*24,y:player.y+dy/d*24,vx:0,vy:0,life:.15,max:.15,r:25,color:'#f0cc8a',ring:true});tone(170,.045,'triangle',.015)}
  function burst(x,y,color,n=8){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),s=rand(30,145);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.2,.6),max:.6,r:rand(1,3),color})}}
  function dropLoot(e){let rarityRoll=Math.random(),it=rarityRoll<.57?itemTable[0]:rarityRoll<.87?itemTable[1+Math.floor(Math.random()*2)]:rarityRoll<.97?itemTable[3+Math.floor(Math.random()*2)]:itemTable[5];drops.push({x:e.x+rand(-9,9),y:e.y+rand(-9,9),type:Math.random()<.73?'gem':'item',item:it,amount:it.rarity==='legendary'?50:it.rarity==='rare'?30:it.rarity==='magic'?18:10,phase:rand(0,6),age:0})}
  function kill(e){let idx=enemies.indexOf(e);if(idx<0)return;enemies.splice(idx,1);kills++;burst(e.x,e.y,e.color,e.kind==='brute'?13:8);dropLoot(e);if(kills%10===0)showToast('THE HOLLOW GROWS HUNGRIER');updateHud()}
  function collect(d){if(d.type==='gem'){xp+=d.amount;tone(580,.09,'sine',.02);while(xp>=xpNeed){xp-=xpNeed;level++;xpNeed=Math.round(xpNeed*1.35+4);openUpgrade()}updateHud()}else{const it=d.item; if(!runLoot.find(q=>q.name===it.name)&&runLoot.length<6){runLoot.unshift(it);applyItem(it);renderLoot();showToast(`${it.rarity.toUpperCase()} FIND  ·  ${it.name.toUpperCase()}`);tone(720,.2,'sine',.035)}else{player.hp=Math.min(player.maxHp,player.hp+12);showToast('RELIC SALVAGED  ·  +12 VITALITY')}updateHud()}}
  function applyItem(it){if(it.name==='Gloomfang')player.damage+=9;else if(it.name==='Widowmaker')player.damage*=1.2;else if(it.name==='Crown of Cinders'){player.maxHp+=30;player.hp+=30}else if(it.name==='Ashen Signet')player.speed*=1.12;else if(it.name==='Worn Bone Ring')player.rate*=.96;else if(it.name==='The Last Promise'){player.damage+=15;player.maxHp+=15;player.hp+=15}if(['Gloomfang','Widowmaker','The Last Promise'].includes(it.name))ui.weapon.textContent=it.name;if(it.name==='Crown of Cinders')ui.armor.textContent=it.name}
  function renderLoot(){ui.lootFeed.innerHTML=runLoot.slice(0,5).map(it=>`<div class="loot-item ${it.rarity}"><span>${it.icon} &nbsp;${it.name}</span><small>${it.rarity.toUpperCase()}</small></div>`).join('')||'<div class="empty-find">The hollow has yet to yield...</div>'}
  function openUpgrade(){state='level';let options=[...upgrades].sort(()=>Math.random()-.5).slice(0,3);$('upgradeChoices').innerHTML=options.map((u,i)=>`<button class="upgrade-choice" data-choice="${i}"><span class="upgrade-icon">${u.icon}</span><b>${u.name}</b><p>${u.desc}</p></button>`).join('');document.querySelectorAll('.upgrade-choice').forEach((el,i)=>el.onclick=()=>{options[i].apply();state='playing';ui.levelModal.classList.add('hidden');updateHud();showToast(`${options[i].name.toUpperCase()} ACQUIRED`);tone(410,.18,'sine',.03);last=performance.now()});ui.levelModal.classList.remove('hidden');tone(350,.12,'sine',.02)}
  function gameOver(){state='dead';ui.endModal.classList.remove('hidden');$('endCopy').textContent=`You survived ${formatTime(elapsed)} and felled ${kills} of the dead.`;$('endStats').innerHTML=`<div><b>${formatTime(elapsed)}</b><small>TIME SURVIVED</small></div><div><b>${kills}</b><small>FELLED</small></div><div><b>${level}</b><small>LEVEL</small></div>`;tone(90,.7,'sawtooth',.04)}
  function formatTime(s){return`${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`}
  function update(dt){if(state!=='playing')return;elapsed+=dt;ui.timer.textContent=formatTime(elapsed);wave=1+Math.floor(elapsed/55);spawnClock-=dt;let spawnRate=Math.max(.24,1.05-elapsed*.004);if(spawnClock<=0){spawnEnemy();if(elapsed>40&&Math.random()<.35)spawnEnemy();spawnClock=spawnRate}let ix=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+touch.x,iy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+touch.y,mag=Math.hypot(ix,iy);if(mag){ix/=mag;iy/=mag}
    if(player.dash>0){player.x+=player.dashDir.x*player.speed*3.2*dt;player.y+=player.dashDir.y*player.speed*3.2*dt;player.dash-=dt;player.invuln=.18;if(Math.random()<.6)particles.push({x:player.x,y:player.y,vx:rand(-10,10),vy:rand(-10,10),life:.25,max:.25,r:rand(3,6),color:'#c29b67'})}else{player.x+=ix*player.speed*dt;player.y+=iy*player.speed*dt}if(ix)player.facing=Math.sign(ix);player.invuln=Math.max(0,player.invuln-dt);player.hp=Math.min(player.maxHp,player.hp+player.regen*dt);dashClock=Math.max(0,dashClock-dt);attackClock-=dt;if(attackClock<=0){attack();attackClock=player.rate}
    for(let e of [...enemies]){e.phase+=dt*4;e.hit=Math.max(0,e.hit-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;let speed=e.speed*(e.kind==='wraith'?1+Math.sin(e.phase)*.15:1);if(d>player.r+e.r+2){e.x+=dx/d*speed*dt;e.y+=dy/d*speed*dt}if(d<player.r+e.r+4&&player.invuln<=0){player.hp-=e.damage*dt;shake=Math.min(8,shake+dt*5);if(player.hp<=0){player.hp=0;updateHud();gameOver();break}}}
    for(let p of projectiles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;for(let e of enemies){if(!p.hit.has(e)&&Math.hypot(e.x-p.x,e.y-p.y)<e.r+8){e.hp-=p.damage;e.hit=.12;p.hit.add(e);burst(p.x,p.y,'#e1ba7b',4);if(e.hp<=0)kill(e)}}}projectiles=projectiles.filter(p=>p.life>0);
    for(let d of drops){d.age+=dt;let dx=player.x-d.x,dy=player.y-d.y,dist=Math.hypot(dx,dy);if(dist<player.magnet+30){let force=dist<player.magnet?4.8:1.9;d.x+=dx/(dist||1)*force*190*dt;d.y+=dy/(dist||1)*force*190*dt}if(dist<player.r+14){collect(d);d.dead=true}}drops=drops.filter(d=>!d.dead);
    for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;p.vx*=.96;p.vy*=.96}particles=particles.filter(p=>p.life>0);shake=Math.max(0,shake-dt*20);if(toastClock>0){toastClock-=dt;if(toastClock<=0)ui.toast.classList.remove('show')}updateHud();}
  function draw(){ctx.setTransform(DPR,0,0,DPR,0,0);ctx.clearRect(0,0,W,H);let ox=W/2-player.x,oy=H/2-player.y;let sx=(Math.random()-.5)*shake,sy=(Math.random()-.5)*shake;ctx.save();ctx.translate(ox+sx,oy+sy);drawGround();for(let d of drops)drawDrop(d);for(let e of enemies)drawEnemy(e);for(let p of projectiles)drawProjectile(p);for(let p of particles)drawParticle(p);if(player)drawPlayer();ctx.restore();drawAtmosphere();if(state==='playing'||state==='level'||state==='pause'||state==='dead')drawMinimap()}
  function drawGround(){let tile=64;let left=player.x-W/2,right=player.x+W/2,top=player.y-H/2,bottom=player.y+H/2;let sx=Math.floor(left/tile)*tile,ex=Math.ceil(right/tile)*tile,sy=Math.floor(top/tile)*tile,ey=Math.ceil(bottom/tile)*tile;ctx.fillStyle='#242720';ctx.fillRect(left-100,top-100,W+200,H+200);for(let x=sx;x<ex;x+=tile)for(let y=sy;y<ey;y+=tile){let n=((Math.floor(x/tile)*73856093)^(Math.floor(y/tile)*19349663))>>>0;ctx.fillStyle=n%4===0?'#292b24':n%4===1?'#262821':'#24261f';ctx.fillRect(x,y,tile,tile);ctx.strokeStyle='#1b1d18';ctx.lineWidth=1;ctx.strokeRect(x,y,tile,tile)}for(let i=0;i<decor.length;i++){let d=decor[i],wx=((d.x+player.x*.08+1400)%2800)-1400+player.x,wy=((d.y+player.y*.08+1100)%2200)-1100+player.y;if(wx<left-10||wx>right+10||wy<top-10||wy>bottom+10)continue;ctx.globalAlpha=d.a;if(d.type==='grass'){ctx.strokeStyle='#737251';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(wx,wy);ctx.lineTo(wx+d.r*.5,wy-d.r);ctx.moveTo(wx,wy);ctx.lineTo(wx-d.r*.5,wy-d.r*.8);ctx.stroke()}else{ctx.fillStyle='#8c8a77';ctx.beginPath();ctx.ellipse(wx,wy,d.r,d.r*.45,.2,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1}for(let i=0;i<13;i++){let tx=player.x+Math.cos(i*5.7+1)*760,ty=player.y+Math.sin(i*7.2)*580;if(tx<left-40||tx>right+40||ty<top-40||ty>bottom+40)continue;drawTree(tx,ty,16+((i*13)%12))} }
  function drawTree(x,y,r){ctx.fillStyle='#171a15';ctx.beginPath();ctx.ellipse(x+3,y+8,r*.8,r*.45,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#33392c';ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3d4030';ctx.beginPath();ctx.arc(x-r*.25,y-r*.25,r*.65,0,Math.PI*2);ctx.fill();ctx.fillStyle='#282c23';ctx.beginPath();ctx.arc(x+r*.36,y-r*.18,r*.42,0,Math.PI*2);ctx.fill()}
  function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);let blink=player.invuln>0&&Math.floor(performance.now()/75)%2===0;ctx.shadowColor='#d7bd8e';ctx.shadowBlur=blink?24:7;ctx.fillStyle=blink?'#f1dfba':'#b0a38b';ctx.beginPath();ctx.ellipse(0,4,11,14,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#3c3830';ctx.beginPath();ctx.ellipse(0,2,7,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d2c2a1';ctx.beginPath();ctx.arc(0,-8,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#211d1a';ctx.beginPath();ctx.arc(0,-10,6,Math.PI,0);ctx.fill();ctx.strokeStyle='#d3b27e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(player.facing*6,-1);ctx.lineTo(player.facing*13,-11);ctx.stroke();ctx.restore();if(player.hp<player.maxHp){ctx.fillStyle='#151513';ctx.fillRect(player.x-15,player.y+19,30,3);ctx.fillStyle='#b84e40';ctx.fillRect(player.x-15,player.y+19,30*player.hp/player.maxHp,3)}}
  function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y+Math.sin(e.phase)*1.3);let c=e.hit?'#f2dfb6':e.color;ctx.shadowColor=e.kind==='wraith'?'#86acb4':'#000';ctx.shadowBlur=e.kind==='wraith'?13:2;ctx.fillStyle=c;ctx.beginPath();if(e.kind==='brute'){ctx.ellipse(0,0,e.r*.9,e.r*1.05,0,0,Math.PI*2)}else if(e.kind==='wraith'){ctx.moveTo(-e.r,-e.r*.35);ctx.quadraticCurveTo(-e.r*1.1,-e.r*1.2,0,-e.r);ctx.quadraticCurveTo(e.r*1.1,-e.r*1.2,e.r,-e.r*.35);ctx.lineTo(e.r*.5,e.r);ctx.lineTo(0,e.r*.45);ctx.lineTo(-e.r*.5,e.r);ctx.closePath()}else{ctx.ellipse(0,0,e.r*.78,e.r,0,0,Math.PI*2)}ctx.fill();ctx.shadowBlur=0;ctx.fillStyle=e.kind==='wraith'?'#b4d2d3':'#d6b98a';ctx.fillRect(-4,-2,2,2);ctx.fillRect(2,-2,2,2);ctx.strokeStyle='#37362e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-e.r*.45,e.r*.65);ctx.lineTo(-e.r*.9,e.r+3);ctx.moveTo(e.r*.45,e.r*.65);ctx.lineTo(e.r*.9,e.r+3);ctx.stroke();if(e.hp<e.max){ctx.fillStyle='#111';ctx.fillRect(-e.r,-e.r-7,e.r*2,2);ctx.fillStyle='#bd5144';ctx.fillRect(-e.r,-e.r-7,e.r*2*e.hp/e.max,2)}ctx.restore()}
  function drawDrop(d){let bob=Math.sin(d.age*4+d.phase)*2;ctx.save();ctx.translate(d.x,d.y+bob);if(d.type==='gem'){ctx.shadowColor='#9fd1c5';ctx.shadowBlur=9;ctx.fillStyle='#8bc7ad';ctx.beginPath();ctx.moveTo(0,-6);ctx.lineTo(5,0);ctx.lineTo(0,6);ctx.lineTo(-5,0);ctx.closePath();ctx.fill();ctx.fillStyle='#d6edca';ctx.fillRect(-1,-3,2,3)}else{ctx.shadowColor=d.item.color;ctx.shadowBlur=12;ctx.fillStyle=d.item.color;ctx.beginPath();ctx.moveTo(0,-7);ctx.lineTo(6,0);ctx.lineTo(0,7);ctx.lineTo(-6,0);ctx.closePath();ctx.fill();ctx.fillStyle='#211e19';ctx.font='8px serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(d.item.icon,0,0)}ctx.restore()}
  function drawProjectile(p){ctx.save();ctx.shadowColor='#f3cd86';ctx.shadowBlur=12;ctx.strokeStyle='#e7c384';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x-p.vx*.028,p.y-p.vy*.028);ctx.lineTo(p.x,p.y);ctx.stroke();ctx.restore()}
  function drawParticle(p){ctx.save();let alpha=clamp(p.life/(p.max||.2),0,1);ctx.globalAlpha=alpha;if(p.ring){ctx.strokeStyle=p.color;ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,p.r*(1-alpha*.45),0,Math.PI*2);ctx.stroke()}else{ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r*alpha,0,Math.PI*2);ctx.fill()}ctx.restore()}
  function drawAtmosphere(){let grad=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.2,W/2,H/2,Math.max(W,H)*.72);grad.addColorStop(0,'rgba(12,13,12,0)');grad.addColorStop(.7,'rgba(8,9,9,.12)');grad.addColorStop(1,'rgba(4,5,6,.68)');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H)}
  function drawMinimap(){let x=W-42,y=H-41,r=22; if(W<700){x=W-29;y=H-250;r=16}ctx.save();ctx.globalAlpha=.72;ctx.fillStyle='#10110f';ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c8ad7b66';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#dfbf82';ctx.beginPath();ctx.arc(x,y,2,0,Math.PI*2);ctx.fill();for(let e of enemies){let dx=(e.x-player.x)/18,dy=(e.y-player.y)/18;if(Math.hypot(dx,dy)>r-4)continue;ctx.fillStyle=e.kind==='brute'?'#d57c58':'#a7554a';ctx.fillRect(x+dx-1,y+dy-1,2,2)}ctx.restore()}
  function loop(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(loop)}
